      if (fl_t2124.tag != FL_NUMBER || fl_t2125.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", fl_t2124, fl_t2125, error));
      const fl_value ostatok = fl_number(fl_t2124.as.number - fl_t2125.as.number); /* пусть «остаток» */
      fl_value fl_t2126 = fl_nothing();
