/* Тело «Назвать сторожей спуска»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nazvat_storozhey_spuska_body(fl_ctx *ctx, fl_value troyki, fl_value zanyatye, fl_value gotovye, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(troyki)) {
      *result = gotovye;
      return FL_OK;
    } else if (fl_chain_cons(troyki)) {
      const fl_value golova = fl_chain_head(troyki); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(troyki); /* хвост «хвост» */
      fl_value fl_t11190 = fl_nothing();
      FL_TRY(kompilyator_flang_svobodnoe_imya_pri_ponizhenii(ctx, kompilyator_flang_text_1224, zanyatye, zanyatye, fl_number(2.0), &fl_t11190, error));
      const fl_value imya = fl_t11190; /* пусть «имя» */
      fl_value fl_t11191 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, imya, zanyatye, &fl_t11191, error));
      fl_value fl_t11193[2];
      fl_t11193[0] = golova; /* «сообщения» */
      fl_t11193[1] = imya; /* «имя» */
      fl_value fl_t11192 = fl_nothing();
      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_62, fl_t11193, 2, &fl_t11192, error));
      fl_value fl_t11194 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t11192, gotovye, &fl_t11194, error));
      troyki = hvost;
      zanyatye = fl_t11191;
      gotovye = fl_t11194;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Назвать сторожей спуска", error));
      continue;
    } else {
      return fl_match_fail(ctx, troyki, error);
    }
  }
}

/*
 * Функция flang «Назвать сторожей спуска».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param troyki — «тройки»: список: «Тройка спуска»
 * @param zanyatye — «занятые»: список: строка
 * @param gotovye — «готовые»: список: «Имя сторожа спуска»
 * @return значение: список: «Имя сторожа спуска»
 */
fl_status kompilyator_flang_nazvat_storozhey_spuska(fl_ctx *ctx, fl_value troyki, fl_value zanyatye, fl_value gotovye, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Назвать сторожей спуска", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_nazvat_storozhey_spuska_body(ctx, troyki, zanyatye, gotovye, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

