static fl_status kompilyator_flang_argument_razrusheniya_body(fl_ctx *ctx, fl_value argumenty, fl_value nomer, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(argumenty)) {
      return kompilyator_flang_neizvestno(ctx, result, error);
    } else if (fl_chain_cons(argumenty)) {
      const fl_value golova = fl_chain_head(argumenty); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(argumenty); /* хвост «хвост» */
      if (nomer.tag != FL_NUMBER) FL_TRY(fl_not_order(ctx, nomer, fl_number(0.0), error));
      bool fl_t19280 = false;
      FL_TRY(fl_cond(ctx, fl_flag(nomer.as.number <= 0.0), &fl_t19280, error));
      if (fl_t19280) {
        fl_value fl_t19281 = fl_nothing();
        FL_TRY(fl_field_get(ctx, golova, "происхождение", &fl_t19281, error));
        *result = fl_t19281;
        return FL_OK;
      } else {
        if (nomer.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", nomer, fl_number(1.0), error));
        const fl_value fl_t19282 = fl_number(nomer.as.number - 1.0);
        argumenty = hvost;
        nomer = fl_t19282;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Аргумент разрушения", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, argumenty, error);
    }
  }
}

